-- Generated by npm run seed:launch:sql

-- Seeds the launch account workflow from imported historical league data.

on conflict (id) do update set
  name = excluded.name,
  short_name = excluded.short_name,
  logo = excluded.logo,
  active = excluded.active,
  updated_at = excluded.updated_at;

delete from public.launch_players
where id in ('ariel-cosmo', 'cecilia-costin', 'chad-hessenflow', 'isaac-kotson', 'jodie-lehmann', 'joshua-matheson');

on conflict (id) do update set
  name = excluded.name,
  gender = excluded.gender,
  pdga_number = excluded.pdga_number,
  pdga_rating = excluded.pdga_rating,
  current_team_id = excluded.current_team_id,
  home_area = excluded.home_area,
  active = excluded.active,
  updated_at = excluded.updated_at;
